def mri_glmfit_outputs(params: MriGlmfit, execution: Execution) -> MriGlmfitOutputs:
    """Build the MriGlmfitOutputs object for this tool."""
    root_v: OutputPathType = execution.output_file(".")
    regression_coefs_v: OutputPathType = execution.output_file("beta.mgh")
    residual_error_v: OutputPathType = execution.output_file("eres.mgh")
    residual_variance_v: OutputPathType = execution.output_file("rvar.mgh")
    residual_stddev_v: OutputPathType = execution.output_file("rstd.mgh")
    fsgd_output_v: OutputPathType = execution.output_file("y.fsgd")
    normalized_weights_v: OutputPathType = execution.output_file("wn.mgh")
    signal_estimate_v: OutputPathType = execution.output_file("yhat.mgh")
    final_mask_v: OutputPathType = execution.output_file("mask.mgh")
    design_condition_v: OutputPathType = execution.output_file("cond.mgh")
    contrast_output_dir_v: OutputPathType = execution.output_file("contrast1name")
    return MriGlmfitOutputs(
        root=root_v,
        regression_coefs=regression_coefs_v,
        residual_error=residual_error_v,
        residual_variance=residual_variance_v,
        residual_stddev=residual_stddev_v,
        fsgd_output=fsgd_output_v,
        normalized_weights=normalized_weights_v,
        signal_estimate=signal_estimate_v,
        final_mask=final_mask_v,
        design_condition=design_condition_v,
        contrast_output_dir=contrast_output_dir_v,
    )

def mri_glmfit_execute(params: MriGlmfit, runner: Runner | None = None) -> MriGlmfitOutputs:
    """
    mri_glmfit

    Performs general linear model (GLM) analysis in the volume or the surface.

    Author: FreeSurfer Developers

    URL: https://github.com/freesurfer/freesurfer

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    mri_glmfit_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(MRI_GLMFIT_METADATA)
    execution.params(params)
    args = mri_glmfit_cargs(params, execution)
    out = mri_glmfit_outputs(params, execution)
    execution.run(args)
    return out

